import { type ReactNode, useState } from "react";
import { Link, useLocation } from "wouter";
import type { Dependencias } from "../../generado/dependencias";
import { marca } from "../../marca/marca";
import { MenuUsuario } from "./menu-usuario";

/** Una sección de la app: una entrada del menú y una tarjeta del panel. */
export interface EntradaMenu {
  etiqueta: string;
  href: string;
  /** Cuántos elementos tiene su lista: lo que enseña el panel. */
  total: (dependencias: Dependencias) => Promise<number>;
}

/**
 * La marca y el menú en un lateral, quien tiene la sesión arriba y el contenido debajo. En una
 * pantalla estrecha el lateral se esconde tras un botón y se cierra al elegir una entrada.
 */
export function Marco({ menu, children }: { menu: EntradaMenu[]; children: ReactNode }) {
  const [ubicacion] = useLocation();
  const [abierto, setAbierto] = useState(false);
  const enlace = (href: string, etiqueta: string) => {
    const actual = ubicacion === href || (href !== "/" && ubicacion.startsWith(`${href}/`));
    return (
      <li key={href}>
        <Link
          href={href}
          className={actual ? "menu-active" : undefined}
          aria-current={actual ? "page" : undefined}
          onClick={() => setAbierto(false)}
        >
          {etiqueta}
        </Link>
      </li>
    );
  };

  return (
    <div className="drawer lg:drawer-open">
      <input
        id="marco-menu"
        type="checkbox"
        className="drawer-toggle"
        checked={abierto}
        onChange={(event) => setAbierto(event.target.checked)}
      />
      <div className="drawer-content flex min-h-screen flex-col bg-base-200">
        <header className="navbar bg-base-100 shadow-sm">
          <label
            htmlFor="marco-menu"
            className="btn btn-square btn-ghost lg:hidden"
            aria-label="Abrir el menú"
          >
            <svg
              viewBox="0 0 24 24"
              className="size-6"
              fill="none"
              stroke="currentColor"
              aria-hidden="true"
            >
              <path strokeLinecap="round" strokeWidth="2" d="M4 6h16M4 12h16M4 18h16" />
            </svg>
          </label>
          <Link href="/" className="flex items-center gap-2 px-2 text-lg font-bold lg:hidden">
            <img src={marca.logo} alt="" className="size-8" />
            {marca.nombre}
          </Link>
          <div className="ml-auto">
            <MenuUsuario />
          </div>
        </header>
        <main className="mx-auto w-full max-w-6xl flex-1 p-4 lg:p-8">{children}</main>
      </div>
      <div className="drawer-side z-20">
        <label htmlFor="marco-menu" className="drawer-overlay" aria-label="Cerrar el menú" />
        <aside className="flex min-h-full w-64 flex-col border-base-300 border-r bg-base-100">
          <Link href="/" className="flex items-center gap-3 p-5 text-xl font-bold">
            <img src={marca.logo} alt="" className="size-10" />
            {marca.nombre}
          </Link>
          <nav>
            <ul className="menu w-full gap-1">
              {enlace("/", "Panel")}
              {menu.map((entrada) => enlace(entrada.href, entrada.etiqueta))}
            </ul>
          </nav>
        </aside>
      </div>
    </div>
  );
}

import { type ReactNode, useState } from "react";
import { Link, useLocation } from "wouter";
import type { Dependencias } from "../../generado/dependencias";
import { marca } from "../../marca/marca";
import { MenuUsuario } from "./menu-usuario";

/** Una sección de la app: una entrada del menú y una tarjeta del panel. */
export interface EntradaMenu {
  etiqueta: string;
  href: string;
  /** Cuántos elementos tiene su lista: lo que enseña el panel. */
  total: (dependencias: Dependencias) => Promise<number>;
}

/**
 * La marca y el menú en una barra arriba, quien tiene la sesión a la derecha y el contenido debajo.
 * En una pantalla estrecha el menú se despliega bajo la barra y se cierra al elegir una entrada.
 */
export function Marco({ menu, children }: { menu: EntradaMenu[]; children: ReactNode }) {
  const [ubicacion] = useLocation();
  const [abierto, setAbierto] = useState(false);
  const enlaces = [{ href: "/", etiqueta: "Panel" }, ...menu].map(({ href, etiqueta }) => {
    const actual = ubicacion === href || (href !== "/" && ubicacion.startsWith(`${href}/`));
    return (
      <li key={href}>
        <Link
          href={href}
          className={actual ? "menu-active" : undefined}
          aria-current={actual ? "page" : undefined}
          onClick={() => setAbierto(false)}
        >
          {etiqueta}
        </Link>
      </li>
    );
  });

  return (
    <div className="flex min-h-screen flex-col bg-base-200">
      <header className="sticky top-0 z-20 bg-base-100 shadow-sm">
        <div className="navbar mx-auto max-w-6xl gap-2 px-4">
          <button
            type="button"
            className="btn btn-square btn-ghost lg:hidden"
            aria-label={abierto ? "Cerrar el menú" : "Abrir el menú"}
            aria-expanded={abierto}
            onClick={() => setAbierto(!abierto)}
          >
            <svg
              viewBox="0 0 24 24"
              className="size-6"
              fill="none"
              stroke="currentColor"
              aria-hidden="true"
            >
              <path strokeLinecap="round" strokeWidth="2" d="M4 6h16M4 12h16M4 18h16" />
            </svg>
          </button>
          <Link href="/" className="flex items-center gap-2 px-2 text-lg font-bold">
            <img src={marca.logo} alt="" className="size-8" />
            {marca.nombre}
          </Link>
          <nav className="hidden lg:block">
            <ul className="menu menu-horizontal gap-1">{enlaces}</ul>
          </nav>
          <div className="ml-auto">
            <MenuUsuario />
          </div>
        </div>
        {abierto && (
          <nav className="border-base-300 border-t lg:hidden">
            <ul className="menu w-full">{enlaces}</ul>
          </nav>
        )}
      </header>
      <main className="mx-auto w-full max-w-6xl flex-1 p-4 lg:p-8">{children}</main>
    </div>
  );
}

import { Link } from "wouter";
import type { EntradaMenu } from "../compartido/ui/marco";
import { SinElementos } from "../compartido/ui/sin-elementos";
import { useCarga } from "../compartido/use-carga";
import { useDependencias } from "../dependencias";
import { marca } from "../marca/marca";

/** La API sirve su Swagger UI en su raíz (`make run`). */
const URL_DOCS_API = "http://localhost:8080/";

/** La página de inicio: una tarjeta por sección, con cuántos elementos tiene. */
export function PaginaPanel({ entradas }: { entradas: EntradaMenu[] }) {
  return (
    <section className="space-y-6">
      <header>
        <h1 className="text-3xl font-bold">Panel</h1>
        <p className="text-base-content/70">{marca.eslogan}</p>
      </header>
      {entradas.length === 0 ? (
        <SinElementos mensaje="Todavía no hay entidades. Añade una con `puerto generar scaffold <Nombre>`." />
      ) : (
        <ul className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">
          {entradas.map((entrada) => (
            <li key={entrada.href}>
              <TarjetaTotal entrada={entrada} />
            </li>
          ))}
        </ul>
      )}
      <a className="link link-hover text-sm" href={URL_DOCS_API}>
        Documentación de la API (Swagger UI)
      </a>
    </section>
  );
}

function TarjetaTotal({ entrada }: { entrada: EntradaMenu }) {
  const dependencias = useDependencias();
  const total = useCarga(() => entrada.total(dependencias), [entrada, dependencias]);
  return (
    <Link
      href={entrada.href}
      className="stats w-full bg-base-100 shadow-sm transition hover:shadow-md"
    >
      <div className="stat">
        <div className="stat-title">{entrada.etiqueta}</div>
        <div className="stat-value text-primary">
          {total.estado === "listo" ? (
            total.datos
          ) : total.estado === "cargando" ? (
            <span className="loading loading-dots" />
          ) : (
            "—"
          )}
        </div>
        <div className="stat-desc">Ver la lista</div>
      </div>
    </Link>
  );
}

